                /**
                 * Naplnění gridu seznamu Dávek
                 *
                 * @param {JQuery} $grid grid
                 */
                fillSeznamDavek($grid, stepWizzard) {
                    let that = this;
                    let defClose = $.Deferred();
                    // filtry
                    let filters = { /*tpep_ano: 1*/};
                    ;
                    let returnObj = {
                        data: null
                    };
                    // deferred objekt pro zřetězení otázek (deferred = odlozeny)
                    let def = $.Deferred().resolve(returnObj).promise();
                    // obsluha jednotlivých fází
                    this.beginOperation();
                    $grid.gcover({ text: "jres:33140096" }); //RC 33140096 : Probíhá načítání vybraných dávek
                    def.then(function (returnObj) {
                        that.isl.DavkaPDB.list({ filters })
                            .get()
                            .then(function (ret) {
                            def = $.Deferred();
                            let view = new Gordic.Data.View(/*ret.data*/ that.vybraneRadky);
                            //Zkontroluj pred odeslanim do banky
                            that.isl.DavkaPDB.zkontrolujPredOdeslanim({ rows: that.vybraneRadky }).get().then(function (retVal) {
                                var countDataPrepare = 0;
                                // nastavení dat a překreslení gridu
                                let dat = view.getDataRows(!true, "data") || [];
                                for (var i = 0; i < dat.length; i++) {
                                    var checkCode = retVal.result[i].kind;
                                    var checkMessage = retVal.result[i].errors[0].message;
                                    dat[i].stav_tra = checkMessage;
                                    dat[i].sbu = checkCode;
                                    //dat[i].tpep_check = true
                                    //if (!dat[i].tpep_check) {
                                    //    dat[i].tpep_check = true;
                                    //}
                                    if (checkCode == 400) {
                                        that.actions?.actContinue?.enabled(false);
                                    }
                                    if (checkCode == 200) {
                                        countDataPrepare++;
                                    }
                                    ////if (!dat[i].tpep_check && errCode != null && errCode <= 50) {
                                    ////    dat[i].tpep_check = false;
                                    ////}
                                    //if (!dat[i].tpep_check && errCode != null && errCode >= 51 && errCode <= 99) {
                                    //    dat[i].tpep_check = true;
                                    //}
                                    //if (!dat[i].tpep_check && errCode != null && errCode == 0) {
                                    //    dat[i].tpep_check = true;
                                    //}
                                }
                                that.flashPanelPocet.gflashpanel({ id: "idCountPrepare", state: "info", content: "Připraveno k odeslání: " + countDataPrepare, disabled: true });
                                view.updateData(dat);
                                $grid.ggrid("setData", view);
                                if (that.kpiPanel != undefined && stepWizzard == 0) {
                                    WebClient.BucWizard.refreshKPIPanelDavka(that.kpiPanel, retVal, false);
                                    $grid.gcover("destroy");
                                    return retVal;
                                }
                                else {
                                    WebClient.BucWizard.refreshKPIPanelDavka(that.kpiPanel, retVal, true);
                                    $grid.gcover("destroy");
                                    return retVal;
                                }
                                $grid.gcover("destroy");
                                that.endOperation();
                                return def.promise();
                            });
                        })
                            .fail(function (xhr, type, vobj) {
                            // operace nedopadla
                            def.reject(xhr, type, vobj);
                        });
                        let def = $.Deferred();
                        //let view = new Gordic.Data.View(that.vybraneRadky);
                        //// nastavení dat a překreslení gridu
                        //$grid.ggrid("setData", view);
                        that.endOperation();
                        return def.promise();
                    }).done(function () {
                    })
                        .always(function () {
                        that.endOperation();
                    });
                    //that.endOperation();
                    return defClose.promise();
                }
